'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var dlarfg = require( './../lib/dlarfg.js' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dlarfg, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 4', function test( t ) {
	t.strictEqual( dlarfg.length, 4, 'returns expected value' );
	t.end();
});

tape( 'the function generates a Householder reflector (N=1)', function test( t ) {
	var tau = dlarfg( 1, 3.0, new Float64Array( 0 ), 1 );
	t.strictEqual( tau, 0.0, 'returns expected value' );
	t.end();
});

tape( 'the function generates a Householder reflector (N=2, positive alpha)', function test( t ) {
	var expected;
	var x;
	var tau;

	x = new Float64Array( [ 3.0 ] );
	tau = dlarfg( 2, 4.0, x, 1 );

	// Expected: H * [4, 3] = [-5, 0]
	// beta = -sqrt(4^2 + 3^2) = -5
	// tau = (beta - alpha) / beta = (-5 - 4) / -5 = 9/5 = 1.8
	expected = 1.8;

	t.strictEqual( tau, expected, 'returns expected tau' );
	
	// v[1] should be x / (alpha - beta) = 3 / (4 - (-5)) = 3/9 = 1/3
	t.strictEqual( x[ 0 ], 1.0/3.0, 'returns expected v[1]' );
	t.end();
});

tape( 'the function generates a Householder reflector (N=2, negative alpha)', function test( t ) {
	var x;
	var tau;

	x = new Float64Array( [ 3.0 ] );
	tau = dlarfg( 2, -4.0, x, 1 );

	// Expected: H * [-4, 3] = [5, 0]
	// beta = sqrt((-4)^2 + 3^2) = 5
	// tau = (beta - alpha) / beta = (5 - (-4)) / 5 = 9/5 = 1.8
	t.strictEqual( tau, 1.8, 'returns expected tau' );
	
	// v[1] should be x / (alpha - beta) = 3 / (-4 - 5) = 3/(-9) = -1/3
	t.strictEqual( x[ 0 ], -1.0/3.0, 'returns expected v[1]' );
	t.end();
});

tape( 'the function generates a Householder reflector (N=3)', function test( t ) {
	var x;
	var tau;

	x = new Float64Array( [ 1.0, 2.0 ] );
	tau = dlarfg( 3, 3.0, x, 1 );

	// Expected: H * [3, 1, 2] = [-sqrt(14), 0, 0]
	// xnorm = sqrt(1^2 + 2^2) = sqrt(5)
	// beta = -sqrt(3^2 + 5) = -sqrt(14)
	// tau = (beta - alpha) / beta
	
	t.ok( tau > 0, 'tau is positive' );
	t.ok( tau < 2, 'tau is less than 2' );
	t.end();
});

tape( 'the function handles zero vector (x = 0)', function test( t ) {
	var x;
	var tau;

	x = new Float64Array( [ 0.0, 0.0 ] );
	tau = dlarfg( 3, 5.0, x, 1 );

	t.strictEqual( tau, 0.0, 'returns tau = 0' );
	t.strictEqual( x[ 0 ], 0.0, 'x[0] unchanged' );
	t.strictEqual( x[ 1 ], 0.0, 'x[1] unchanged' );
	t.end();
});

tape( 'the function supports stride', function test( t ) {
	var x;
	var tau;

	x = new Float64Array( [ 1.0, 999.0, 2.0, 999.0 ] );
	tau = dlarfg( 3, 3.0, x, 2 );

	t.ok( tau > 0, 'tau is positive' );
	t.notEqual( x[ 0 ], 1.0, 'x[0] modified' );
	t.strictEqual( x[ 1 ], 999.0, 'x[1] unchanged (stride skip)' );
	t.notEqual( x[ 2 ], 2.0, 'x[2] modified' );
	t.strictEqual( x[ 3 ], 999.0, 'x[3] unchanged (stride skip)' );
	t.end();
});

tape( 'the function supports negative stride', function test( t ) {
	var x;
	var tau;

	x = new Float64Array( [ 2.0, 1.0 ] );
	tau = dlarfg( 3, 3.0, x, -1 );

	t.ok( tau > 0, 'tau is positive' );
	t.end();
});
